import{latestFor}from"./latest.011583db.js";const WB={label:"World Bank Pink Sheet",href:"https://www.worldbank.org/en/research/commodity-markets"};const IGC={label:"IGC market information",href:"https://www.igc.int/public-site/Market-transparency.aspx"};const ACCESS={wb_pink_monthly:WB,wb_pink_indices:WB,fdw_intl_prices:{label:"FEWS NET Data Warehouse",href:"https://fdw.fews.net/"},fpma_intl:{label:"FAO GIEWS FPMA tool",href:"https://fpma.fao.org/giews/fpmat4/#/dashboard/tool/international"},eia_steo:{label:"EIA Short-Term Energy Outlook",href:"https://www.eia.gov/outlooks/steo/"},igc_gofi:IGC,imf_portwatch:{label:"IMF PortWatch",href:"https://portwatch.imf.org/"},fao_fpi:{label:"FAO Food Price Index",href:"https://www.fao.org/worldfoodsituation/foodpricesindex/en/"},fred:{label:"FRED, Federal Reserve Bank of St. Louis",href:"https://fred.stlouisfed.org/"},igc_goi:IGC,igc_quotes:{label:"IGC home page, daily export prices",href:"https://www.igc.int/en/default.aspx"}};const PAGES=[{title:"Maize",path:"maize",sections:["MAIZE"]},{title:"Rice",path:"rice",sections:["RICE"]},{title:"Wheat",path:"wheat",sections:["WHEAT"]},{title:"Oilseeds",path:"oilseeds",sections:["OILSEEDS"]},{title:"Crude oil",path:"crude-oil",sections:["CRUDE"]},{title:"Natural gas",path:"natural-gas",sections:["GAS"]},{title:"Fertilizer",path:"fertilizer",sections:["FERT"]},{title:"FAO Food Price Index",path:"food-price-index",fpi:true},{title:"Metals",path:"metals",sections:["METALS","WBINDEX"]},{title:"Shipping",path:"shipping",sections:["SHIPPING","CHOKEPOINTS"]},{title:"Daily prices",path:"daily"}];const DAILY_SOURCES=[{page:"daily",publisher:"EIA",access:"fred",series:["Brent spot (Europe, FOB)","WTI spot (Cushing, OK)","Henry Hub spot"]},{page:"daily",publisher:"IGC",access:"igc_goi",series:["Grains and Oilseeds Index (GOI), with wheat, maize, rice and soyabean sub-indices"]},{page:"shipping",publisher:"IGC",access:"igc_gofi",series:["Grains and Oilseeds Freight Index (GOFI), all routes and by origin"]},{page:"shipping",publisher:"IMF PortWatch",access:"imf_portwatch",series:["Vessel transits: Bab el-Mandeb, Suez Canal, Cape of Good Hope, Panama Canal, Bosporus, Malacca Strait"]}];function sourceRows(prices,fpi,latest=new Map){const rows=[];for(const page of PAGES){const groups=new Map;const add=(publisher,code,frequency,series)=>{const access=ACCESS[code]??{label:code};const key=[publisher,access.label,frequency].join("|");if(!groups.has(key))groups.set(key,{page,publisher,frequency,access,series:[]});const group=groups.get(key);if(!group.series.includes(series))group.series.push(series)};for(const d of DAILY_SOURCES.filter(d2=>d2.page===page.path)){for(const s of d.series)add(d.publisher,d.access,"Daily",s)}const pagePrices=prices.filter(r=>page.sections?.includes(r.section));for(const r of pagePrices)add(r.cite_as,r.source,"Monthly",r.name.split(" \u2014 ")[0]);for(const r of pagePrices){const quote=latestFor(r,latest);if(quote)add(quote.publisher,quote.route,`${quote.frequency}, latest price`,quote.quote)}if(page.fpi)for(const r of fpi)add(r.cite_as,"fao_fpi","Monthly",r.name);rows.push(...groups.values())}return rows}export{ACCESS,DAILY_SOURCES,PAGES,sourceRows};
